import java.text.ParsePosition;
import java.util.Calendar;
import java.util.Locale;
import java.util.TimeZone;
import org.apache.commons.lang3.time.FastDateParser;

public class Scratch {
    static class P extends FastDateParser {
        P(String p, TimeZone tz, Locale l) { super(p, tz, l); }
    }
    public static void main(String[] args) throws Exception {
        P parser = new P("yyyy-MM-dd", TimeZone.getTimeZone("UTC"), Locale.US);
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"), Locale.US);
        cal.clear();
        cal.setLenient(false);
        ParsePosition pos = new ParsePosition(0);
        try {
            boolean ok = parser.parse("2020-13-40", pos, cal);
            System.out.println("ok=" + ok + " pos=" + pos);
        } catch (IllegalArgumentException e) {
            System.out.println("IAE: " + e.getMessage());
        }
    }
}
